// --- Migrator -----------------------------------------------------------------
// Re-exports Migrator from kysely and provides a convenience createMigrator
// that uses the generated migrations/index.ts barrel file.

import { Migrator } from "kysely";
import type { Kysely, Migration, MigrationProvider, MigrationResultSet } from "kysely";

/**
 * Create a MigrationProvider from a bundled migrations record.
 * The migrations record is generated by the Vite plugin at
 * `src/db/<name>/migrations/index.ts`.
 *
 * No fs, no path — fully bundleable for edge runtimes.
 */
export function createMigrationProvider(migrations: Record<string, Migration>): MigrationProvider {
	return {
		async getMigrations() {
			return migrations;
		},
	};
}

/**
 * Create a Kysely Migrator with the given database and bundled migrations.
 *
 * @example
 * ```ts
 * import { createMigrator } from "@spacefn/db"
 * import { migrations } from "./main/migrations"
 *
 * const migrate = createMigrator(db, migrations)
 * const { error, results } = await migrate.migrateToLatest()
 * ```
 */
export function createMigrator(
	db: Kysely<any>,
	migrations: Record<string, Migration>,
): {
	migrateToLatest(): Promise<MigrationResultSet>;
	migrateUp(): Promise<MigrationResultSet>;
	migrateDown(): Promise<MigrationResultSet>;
} {
	const migrator = new Migrator({
		db,
		provider: createMigrationProvider(migrations),
	});
	return {
		migrateToLatest: () => migrator.migrateToLatest(),
		migrateUp: () => migrator.migrateUp(),
		migrateDown: () => migrator.migrateDown(),
	};
}
